import{_ as e,H as t,f as s,i}from"./chunks/framework.Cvt1eIE0.js";const u=JSON.parse('{"title":"第六章：编辑和创建代码","description":"学会让 Claude 直接帮你写代码、修改代码","frontmatter":{"title":"第六章：编辑和创建代码","description":"学会让 Claude 直接帮你写代码、修改代码"},"headers":[],"relativePath":"guide/2-basic-usage/6-edit-code.md","filePath":"guide/2-basic-usage/6-edit-code.md"}'),l={name:"guide/2-basic-usage/6-edit-code.md"};function n(o,a,d,r,p,h){return t(),s("div",null,[...a[0]||(a[0]=[i(`<h1 id="第六章-编辑和创建代码" tabindex="-1">第六章：编辑和创建代码 <a class="header-anchor" href="#第六章-编辑和创建代码" aria-label="Permalink to &quot;第六章：编辑和创建代码&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">学习目标</p><p>学完这章，你会让 Claude 帮你创建新文件和修改现有文件。</p></div><h2 id="两种编辑方式" tabindex="-1">两种编辑方式 <a class="header-anchor" href="#两种编辑方式" aria-label="Permalink to &quot;两种编辑方式&quot;">​</a></h2><ol><li><strong>直接生成</strong>：让 Claude 写完整代码，你复制使用</li><li><strong>渐进式修改</strong>：让 Claude 直接修改你的文件</li></ol><h2 id="创建新文件" tabindex="-1">创建新文件 <a class="header-anchor" href="#创建新文件" aria-label="Permalink to &quot;创建新文件&quot;">​</a></h2><h3 id="直接问" tabindex="-1">直接问 <a class="header-anchor" href="#直接问" aria-label="Permalink to &quot;直接问&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>帮我创建一个 sum.py，实现加法函数</span></span></code></pre></div><p>Claude 会给你完整的代码。</p><h3 id="复制使用" tabindex="-1">复制使用 <a class="header-anchor" href="#复制使用" aria-label="Permalink to &quot;复制使用&quot;">​</a></h3><p>把代码复制到你的编辑器，保存文件。</p><h2 id="修改现有文件" tabindex="-1">修改现有文件 <a class="header-anchor" href="#修改现有文件" aria-label="Permalink to &quot;修改现有文件&quot;">​</a></h2><h3 id="使用-edit-命令" tabindex="-1">使用 /edit 命令 <a class="header-anchor" href="#使用-edit-命令" aria-label="Permalink to &quot;使用 /edit 命令&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/edit</span></span></code></pre></div><p>Claude 会进入编辑模式。</p><h3 id="描述你要改什么" tabindex="-1">描述你要改什么 <a class="header-anchor" href="#描述你要改什么" aria-label="Permalink to &quot;描述你要改什么&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>把这个函数的返回值从 int 改成 float</span></span></code></pre></div><p>Claude 会生成修改后的代码，询问你是否接受。</p><h3 id="接受或拒绝" tabindex="-1">接受或拒绝 <a class="header-anchor" href="#接受或拒绝" aria-label="Permalink to &quot;接受或拒绝&quot;">​</a></h3><ul><li><strong>Apply</strong>：接受修改</li><li><strong>Reject</strong>：拒绝，重新生成</li><li><strong>部分接受</strong>：可以手动微调</li></ul><h2 id="一定要审查代码" tabindex="-1">一定要审查代码！ <a class="header-anchor" href="#一定要审查代码" aria-label="Permalink to &quot;一定要审查代码！&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">重要</p><p>Claude 写的代码一定要看一遍再使用！</p></div><p>Claude 可能：</p><ul><li>有 bug</li><li>不符合你的编码习惯</li><li>有安全风险</li></ul><p>你是最后把关的人。</p><h2 id="如何要求重写" tabindex="-1">如何要求重写 <a class="header-anchor" href="#如何要求重写" aria-label="Permalink to &quot;如何要求重写&quot;">​</a></h2><p>如果 Claude 写的不好：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>不要这个方案，换一个</span></span>
<span class="line"><span></span></span>
<span class="line"><span>或者</span></span>
<span class="line"><span></span></span>
<span class="line"><span>这个不对，请用 XXX 方式重写</span></span></code></pre></div><h2 id="前置知识" tabindex="-1">前置知识 <a class="header-anchor" href="#前置知识" aria-label="Permalink to &quot;前置知识&quot;">​</a></h2><p>知道代码文件存在哪。</p><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><p><strong>Q: Claude 写的代码报错？</strong></p><p>A: 把错误信息粘贴给 Claude，让它修复。</p><p><strong>Q: 不想用 Claude 写的？</strong></p><p>A: 直接说&quot;不要这个方案，换一个&quot;。</p><p><strong>Q: 怎么只接受部分修改？</strong></p><p>A: 可以手动微调，Claude 不会介意。</p><h2 id="练习题" tabindex="-1">练习题 <a class="header-anchor" href="#练习题" aria-label="Permalink to &quot;练习题&quot;">​</a></h2><ol><li>让 Claude 帮你写一个&quot;学生成绩管理&quot;程序</li><li>让它添加&quot;添加学生&quot;和&quot;查看成绩&quot;功能</li></ol><h2 id="下一章" tabindex="-1">下一章 <a class="header-anchor" href="#下一章" aria-label="Permalink to &quot;下一章&quot;">​</a></h2><p>下一章我们会学习如何通过多轮对话完善代码。</p><p><a href="/guide/2-basic-usage/7-multi-turn.html">👉 第七章：多轮对话技巧</a></p>`,41)])])}const b=e(l,[["render",n]]);export{u as __pageData,b as default};
